        />

        <MetricCard
          label="Orders"
          value={
            loadingOrders ? "—" : orders.length
          }
          description="Total customer orders"
        />

        <MetricCard
          label="Pending"
          value={
            loadingOrders
              ? "—"
              : pendingOrders
          }
          description="Orders requiring attention"
        />

        <MetricCard
          label="Total sales"
          value={
            loadingOrders
              ? "—"
              : `₹${totalSales.toLocaleString(
                  "en-IN"
                )}`
          }
