        </div>
      )}

      {!loading && products.length > 0 && (
        <div className="admin-product-list">
          {products.map((product) => (
            <article
              key={product._id}
              className="admin-product-row"
            >
              <div className="admin-product-thumbnail">
                {product.imageUrl ? (
                  <img
                    src={product.imageUrl}
                    alt={product.name}
